  "tr5-broadcast-neighbor-discovery": {
    id: "tr5-broadcast-neighbor-discovery",
    tranche: 5,
    type: "guided",
    title: "Broadcasts and IPv6 Neighbor Discovery",
    description: "Compare IPv4 broadcast behavior with IPv6 multicast-based neighbor discovery and verify both on a dual-stack interface.",
    topology: { devices: [{ id: "r1", name: "CE-R1", kind: "router", role: "Dual-Stack Gateway", x: 350, y: 180, ports: ["g0/0"] }, { id: "pc1", name: "DISCOVERY-PC1", kind: "pc", role: "Dual-Stack Host", x: 700, y: 180, ports: ["eth0"] }], links: [{ id: "l1", from: "r1", to: "pc1", fromPort: "g0/0", toPort: "eth0" }] },
    initialState: {},
    steps: [
      { id: 1, label: "Privileged Mode", description: "Enter Privileged EXEC mode on the dual-stack gateway.", targetDevice: "CE-R1", requiredMode: "user", expectedCommand: "enable", successMessage: "CE-R1 is ready for broadcast and neighbor discovery practice.", validation: (state) => true },
      { id: 2, label: "Global Configuration", description: "Enter Global Configuration mode.", targetDevice: "CE-R1", requiredMode: "privileged", expectedCommand: "configure terminal", successMessage: "Global Configuration mode is active.", validation: (state) => true },
      { id: 3, label: "Enable IPv6 Routing", description: "Enable IPv6 forwarding for the dual-stack gateway.", targetDevice: "CE-R1", requiredMode: "config", expectedCommand: "ipv6 unicast-routing", successMessage: "IPv6 forwarding is enabled.", validation: (state) => true },
      { id: 4, label: "Select LAN Interface", description: "Open the LAN interface where IPv4 broadcast and IPv6 neighbor discovery will operate.", targetDevice: "CE-R1", requiredMode: "config", expectedCommand: "interface g0/0", successMessage: "The dual-stack LAN interface is selected.", validation: (state) => true },
      { id: 5, label: "Address IPv4 LAN", description: "Configure 192.168.70.1/24. The all-hosts broadcast address for this subnet is 192.168.70.255.", targetDevice: "CE-R1", requiredMode: "interface", expectedCommand: "ip address 192.168.70.1 255.255.255.0", successMessage: "The IPv4 LAN and its broadcast boundary are configured.", validation: (state) => true },
      { id: 6, label: "Address IPv6 LAN", description: "Configure 2001:db8:700::1/64. IPv6 does not use an all-hosts broadcast address.", targetDevice: "CE-R1", requiredMode: "interface", expectedCommand: "ipv6 address 2001:db8:700::1/64", successMessage: "The IPv6 LAN prefix is configured.", validation: (state) => true },
      { id: 7, label: "Set IPv6 Prefix", description: "Advertise the /64 prefix to hosts through IPv6 Neighbor Discovery.", targetDevice: "CE-R1", requiredMode: "interface", expectedCommand: "ipv6 nd prefix 2001:db8:700::/64", successMessage: "The IPv6 prefix advertisement is configured.", validation: (state) => true },
      { id: 8, label: "Enable Directed Broadcast", description: "Permit directed broadcasts on this controlled practice interface so the IPv4 concept can be observed in IOS.", targetDevice: "CE-R1", requiredMode: "interface", expectedCommand: "ip directed-broadcast", successMessage: "Directed broadcast behavior is enabled for the exercise.", validation: (state) => true },
      { id: 9, label: "Activate Interface", description: "Enable the dual-stack LAN interface.", targetDevice: "CE-R1", requiredMode: "interface", expectedCommand: "no shutdown", successMessage: "The dual-stack LAN is active.", validation: (state) => true },
      { id: 10, label: "Verify Addressing", description: "Return to Privileged EXEC and inspect IPv4 and IPv6 interface state.", targetDevice: "CE-R1", requiredMode: "interface", expectedCommand: "end", successMessage: "Privileged EXEC is ready for discovery verification.", validation: (state) => true },
      { id: 11, label: "Show IPv4 Broadcast Context", description: "Review the IPv4 interface output and identify the subnet broadcast address.", targetDevice: "CE-R1", requiredMode: "privileged", expectedCommand: "show ip interface g0/0", successMessage: "The IPv4 broadcast context is visible.", validation: (state) => true },
      { id: 12, label: "Show IPv6 Neighbor Context", description: "Review the IPv6 interface output and identify link-local and neighbor discovery behavior.", targetDevice: "CE-R1", requiredMode: "privileged", expectedCommand: "show ipv6 interface g0/0", successMessage: "The IPv6 neighbor-discovery context is visible.", validation: (state) => true },
      { id: 13, label: "Show IPv6 Neighbors", description: "Inspect the IPv6 neighbor cache built from multicast Neighbor Solicitation and Advertisement messages.", targetDevice: "CE-R1", requiredMode: "privileged", expectedCommand: "show ipv6 neighbors", successMessage: "The IPv6 neighbor cache has been reviewed.", validation: (state) => true },
    ],
  },
