function addMissingActivationSteps(lab: LabConfig) {
  const steps = [...lab.steps];
  const isActivatableInterface = (command: string) => /^interface (?:g\d+\/\d+|gigabitethernet ?\d+\/\d+|vlan \d+|port-channel ?\d+)$/.test(command);
  const additions: { index: number; step: LabStep }[] = [];

  steps.forEach((step, index) => {
    if (!isActivatableInterface(step.expectedCommand)) return;
    const blockEnd = steps.findIndex((candidate, candidateIndex) => candidateIndex > index && (candidate.expectedCommand === "exit" || candidate.expectedCommand === "end" || candidate.expectedCommand.startsWith("interface ")));
    const end = blockEnd === -1 ? steps.length : blockEnd;
    if (steps.slice(index + 1, end).some((candidate) => candidate.expectedCommand === "no shutdown")) return;
    additions.push({
      index: end,
      step: {
        id: 0,
        label: `Enable ${step.expectedCommand.slice("interface ".length)}`,
        description: `Administratively enable ${step.expectedCommand.slice("interface ".length)} so the connected network path can become operational.`,
        targetDevice: step.targetDevice,
        requiredMode: "interface",
        expectedCommand: "no shutdown",
        successMessage: `${step.expectedCommand.slice("interface ".length)} is administratively enabled.`,
        validation: () => true,
      },
    });
  });

  for (let offset = additions.length - 1; offset >= 0; offset -= 1) {
    const addition = additions[offset];
    steps.splice(addition.index, 0, addition.step);
  }
  steps.forEach((step, index) => { step.id = index + 1; });
  lab.steps = steps;
}

for (const lab of Object.values(LAB_REGISTRY)) addMissingActivationSteps(lab);

type PracticeExtension = {
  targetLength: number;
  targetDevice: string;
  commands: string[];
};
type ModeledTrafficStep = {
  targetDevice: string;
  command: string;
  label: string;
  description: string;
  successMessage: string;
};

